// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    BANK_SAFE c;
    function setUp() public { c = new BANK_SAFE(); }
    function testFuzz_property(uint256 _val, address caller) public {
        vm.assume(_val <= type(uint256).max - 1);
        vm.assume(caller != address(0));
        vm.prank(caller);
        c.SetMinSum(_val);
        assertTrue(c.MinSum() == _val);
    }
}
